package kr.seoulhousing.alerts;
import android.content.*; import android.net.Uri; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import org.json.*;
public class AnnouncementDetailActivity extends AppCompatActivity {
    @Override public void onCreate(Bundle state) { super.onCreate(state); setContentView(R.layout.activity_detail); String id=getIntent().getStringExtra("announcementId"); TextView title=findViewById(R.id.detail_title),body=findViewById(R.id.detail_body); Button official=findViewById(R.id.open_official); ApiClient.request(this,"GET","announcements/"+id,null,(json,error)->runOnUiThread(()-> { if(error!=null){title.setText("공고를 불러올 수 없습니다.");return;} JSONObject item=json.optJSONObject("announcement"),details=json.optJSONObject("details"); title.setText(item.optString("title")); String text="출처: "+item.optString("sourceName")+"\n상태: "+item.optString("status")+"\n접수 마감: "+item.optString("applicationEnd"); if(details!=null){JSONObject location=details.optJSONObject("location"),cost=details.optJSONObject("cost"); text+="\n위치: "+(location==null?"미확인":location.optString("district")+" "+location.optString("address")); text+="\n보증금: "+(cost==null?"미확인":cost.optString("depositMinWon","미확인"));} else text+="\n상세 정보: 공고문에서 상세 확인 필요"; body.setText(text); official.setOnClickListener(v->{String url=item.optString("officialUrl"); if(!url.isBlank()) startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(url)));}); })); }
}
